#!/usr/bin/env python3
"""Write prompts/PROMPTS.md: every rubric, criterion and question wording that run_raters.py sends (single source of truth)."""
import json, sys
from pathlib import Path
HERE = Path(__file__).resolve().parent
src = (HERE / "run_raters.py").read_text().replace('if __name__ == "__main__":\n    main()', "")
ns = {"__file__": str(HERE / "run_raters.py")}
exec(compile(src, "run_raters", "exec"), ns)
V4 = "4" in sys.argv[1:]
V7 = "7" in sys.argv[1:]
V6 = "6" in sys.argv[1:] or V7
def block(title, d): return f"### {title}\n\n" + "\n".join(f"- **{k}**: {v}" for k, v in d.items()) + "\n"
ex = json.loads((HERE / "examples/fidelity_examples.json").read_text())
out = ["# Prompts sent to the decision models", "", "Generated by `dump_prompts.py` from `run_raters.py`. The models get this text plus the per-EVD inputs shown in `prompts/rendered/`.", "",
       "## Relevancy: review criterion (shown after the EVD's review question(s))", "", ns["CRITERION"], "",
       "Question: *Is this EVD relevant to the REVIEW QUESTION(S) and the REVIEW CRITERION, and worth learning? Yes means Relevant; No means Irrelevant.*", "",
       ("## Fidelity (version 4, used in runs r4-r6)" if (V4 or V6) else "## Fidelity (version 3, used in runs r1-r3)"), "", "Question: *Is the gist of the EVD statement in the quoted text? Choose Met when its main finding is there; missing specific numbers or details do not matter.*", "",
       block("Options", ns["FIDELITY_V4" if (V4 or V6) else "FIDELITY_V2"]), "Worked examples (EVD 1-3, JP's Fidelity ratings; EVD 1-3 are skipped for this task):", ""]
for e in ex["examples"]: out += [f"- EVD {e['evd']}: {e['evd_statement']} -> **{e['label']}**. {e['why']}"]
out += ["", "## Grounding: Quote", "", "Question: *Do the screenshots on the evidence page correctly show the quoted text?* Also asked: *Does any SCREENSHOT show the quoted passage?* and, for each screenshot k, *Does SCREENSHOT k show text or a table or figure that connects to the quoted text?* (Run 1 asked only about the screenshot in the quote slot.)", "", block("Options", ns["QUOTE_V7" if V7 else "QUOTE_V6" if V6 else ("QUOTE_V4" if V4 else "QUOTE")]),
        "## Grounding: Table/Figure", "", "Question: *Does the evidence page show the correct table or figure for the EVD statement's numbers?*", "", block("Options", ns["TABLE_V7" if V7 else "TABLE_V6" if V6 else "TABLE"]),
        "Run 2 inputs: every Description screenshot on the page is shown without slot labels, with the caption and the paraphrased text under the table/figure. Also asked per screenshot k: *Does SCREENSHOT k show text or a table or figure that connects to the quoted text?* Missing by rule only when the page has no screenshot at all (no model call).", ""]
(HERE / "prompts").mkdir(exist_ok=True)
(HERE / "prompts/PROMPTS.md").write_text("\n".join(out) + (("\n\n" + ns["QUOTE_EXAMPLES_V7" if V7 else "QUOTE_EXAMPLES_V6"] + "\n" + ns["TABLE_EXAMPLES_V7" if V7 else "TABLE_EXAMPLES_V6"] + "\n") if V6 else "") + ("\n\nRun 4 adds one question to the quote task: *Is every word of the quoted text visible and legible in the screenshots (surrounding text, highlighting and neighbouring content do not matter)?*\n" if (V4 or V6) else "")); print("prompts/PROMPTS.md written")
